function rampartSimulate(createStrategy, seed, maxTicks, recorder) {
  "use strict";
  var TT = ["bolt", "cannon", "frost", "lance", "flak"];
  var TD = {
    bolt:   { cost: 50,  dmg: 26,  period: 8,  range: 300, splash: 0,  slow: 0,  pierce: false, ground: true,  air: true  },
    cannon: { cost: 90,  dmg: 60,  period: 24, range: 260, splash: 90, slow: 0,  pierce: false, ground: true,  air: false },
    frost:  { cost: 70,  dmg: 10,  period: 12, range: 240, splash: 0,  slow: 30, pierce: false, ground: true,  air: true  },
    lance:  { cost: 120, dmg: 180, period: 36, range: 360, splash: 0,  slow: 0,  pierce: true,  ground: true,  air: false },
    flak:   { cost: 80,  dmg: 40,  period: 10, range: 320, splash: 70, slow: 0,  pierce: false, ground: false, air: true  }
  };
  var ET = ["grunt", "runner", "wisp", "brute", "splitter", "mender"];
  var ED = {
    grunt:     { hp: 60,  speed: 10, bounty: 4, leak: 1, air: 0, first: 1, weight: 10 },
    runner:    { hp: 40,  speed: 20, bounty: 4, leak: 1, air: 0, first: 2, weight: 4 },
    wisp:      { hp: 50,  speed: 12, bounty: 6, leak: 2, air: 1, first: 3, weight: 3 },
    brute:     { hp: 150, speed: 6,  bounty: 9, leak: 3, air: 0, first: 4, weight: 3 },
    splitter:  { hp: 90,  speed: 8,  bounty: 6, leak: 2, air: 0, first: 6, weight: 2 },
    mender:    { hp: 70,  speed: 8,  bounty: 7, leak: 2, air: 0, first: 8, weight: 1 },
    splitling: { hp: 0,   speed: 12, bounty: 1, leak: 1, air: 0, first: 0, weight: 0 }
  };
  function armorOf(type, w) {
    if (type === "grunt") return Math.floor(w / 4);
    if (type === "brute") return 6 + w;
    return 0;
  }
  function mkRoute(pts) {
    var p = [], i, len = 0, segs = [];
    for (i = 0; i < pts.length; i++) p.push([pts[i][0] * 100 + 50, pts[i][1] * 100 + 50]);
    for (i = 0; i + 1 < p.length; i++) {
      var l = Math.abs(p[i + 1][0] - p[i][0]) + Math.abs(p[i + 1][1] - p[i][1]);
      segs.push({ x0: p[i][0], y0: p[i][1], dx: Math.sign(p[i + 1][0] - p[i][0]), dy: Math.sign(p[i + 1][1] - p[i][1]), s: len, l: l });
      len += l;
    }
    return { segs: segs, len: len };
  }
  var ROUTES = [
    mkRoute([[0, 2], [6, 2], [6, 10], [12, 10], [12, 3], [18, 3], [18, 11], [23, 11]]),
    mkRoute([[0, 6], [21, 6], [21, 11], [23, 11]])
  ];
  function place(e) {
    var r = ROUTES[e.air], s = r.segs, p = e.progress, i = 0;
    while (i < s.length - 1 && p >= s[i].s + s[i].l) i++;
    var d = p - s[i].s; if (d > s[i].l) d = s[i].l;
    e.x = s[i].x0 + s[i].dx * d; e.y = s[i].y0 + s[i].dy * d;
  }
  var SLOTS = [[3, 3], [5, 5], [7, 4], [7, 8], [9, 9], [10, 5], [11, 8], [13, 8], [14, 5], [15, 2], [16, 7], [17, 4], [19, 8], [20, 10], [22, 9], [3, 7]];
  var M = [0, 1000];
  for (var mw = 2; mw <= 400; mw++) M.push(Math.floor(M[mw - 1] * 108 / 100));
  function mulberry32(a) { return function () {
    a = (a + 0x6D2B79F5) | 0; var t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return (t ^ (t >>> 14)) >>> 0; }; }
  var rng = mulberry32(seed);
  function genWave(w) {
    var n = 4 + Math.floor(3 * w / 5), out = [], tot = 0, k, i;
    for (k = 0; k < ET.length; k++) if (ED[ET[k]].first <= w) tot += ED[ET[k]].weight;
    for (i = 0; i < n; i++) {
      var r = rng() % tot;
      for (k = 0; k < ET.length; k++) {
        var d = ED[ET[k]];
        if (d.first > w) continue;
        if (r < d.weight) { out.push(ET[k]); break; }
        r -= d.weight;
      }
    }
    return out;
  }
  function tierDmg(base, tier) { var d = base; for (var i = 1; i < tier; i++) d = Math.floor(d * 16 / 10); return d; }

  var strat = createStrategy();
  var log = [];
  var gold = 250, baseHp = 10, wave = 0, nextId = 1, fallTick = -1;
  var slots = [];
  for (var si = 0; si < 16; si++) slots.push({ slot: si, x: SLOTS[si][0] * 100 + 50, y: SLOTS[si][1] * 100 + 50, t: null });
  var enemies = [];
  var queue = [];
  var waves = [null, genWave(1)];
  var tick, endTick = maxTicks;

  function makeEnemy(type, w, hp, progress) {
    var d = ED[type];
    var e = { id: nextId++, type: type, wave: w, maxHp: hp, hp: hp, speed: d.speed, armor: armorOf(type, w), air: d.air,
      bounty: d.bounty, leak: d.leak, progress: progress, age: 0, slow: 0, x: 0, y: 0 };
    place(e);
    return e;
  }
  function view(e) {
    return { id: e.id, type: e.type, hp: e.hp, maxHp: e.maxHp, x: e.x, y: e.y, air: e.air, armor: e.armor, speed: e.speed,
      slowed: e.slow, remaining: ROUTES[e.air].len - e.progress };
  }
  function turretStats(t) {
    var d = TD[t.type];
    return { dmg: tierDmg(d.dmg, t.tier), range: d.range + 30 * (t.tier - 1) };
  }
  function applyAction(a) {
    if (!a || typeof a !== "object") return;
    var s = a.slot;
    if (typeof s !== "number" || s !== Math.floor(s) || s < 0 || s > 15) return;
    var sl = slots[s];
    if (a.op === "build") {
      if (sl.t || !Object.prototype.hasOwnProperty.call(TD, a.type)) return;
      var c = TD[a.type].cost;
      if (gold < c) return;
      gold -= c;
      sl.t = { type: a.type, tier: 1, spent: c, cd: 0 };
      var st = turretStats(sl.t); sl.t.dmg = st.dmg; sl.t.range = st.range;
      log.push([tick, "B", s, TT.indexOf(a.type)]);
      if (recorder && recorder.onAction) recorder.onAction(tick, "B", s, a.type, 1);
    } else if (a.op === "upgrade") {
      if (!sl.t || sl.t.tier >= 3) return;
      var uc = TD[sl.t.type].cost * (sl.t.tier === 1 ? 1 : 2);
      if (gold < uc) return;
      gold -= uc; sl.t.spent += uc; sl.t.tier++;
      var st2 = turretStats(sl.t); sl.t.dmg = st2.dmg; sl.t.range = st2.range;
      log.push([tick, "U", s, sl.t.tier]);
      if (recorder && recorder.onAction) recorder.onAction(tick, "U", s, sl.t.type, sl.t.tier);
    } else if (a.op === "sell") {
      if (!sl.t) return;
      var ty = sl.t.type;
      gold += Math.floor(sl.t.spent * 70 / 100);
      sl.t = null;
      log.push([tick, "S", s, 0]);
      if (recorder && recorder.onAction) recorder.onAction(tick, "S", s, ty, 0);
    }
  }

  for (tick = 0; tick < maxTicks; tick++) {
    // 1. wave start
    if (tick >= 20 && (tick - 20) % 40 === 0) {
      wave = (tick - 20) / 40 + 1;
      gold += Math.min(50, Math.floor(gold * 5 / 100)) + 10 + 2 * wave;
      waves[wave + 1] = genWave(wave + 1);
      var st = { tick: tick, wave: wave, gold: gold, baseHp: baseHp, slots: [], enemies: [], nextWave: waves[wave + 1].slice() };
      for (var a = 0; a < 16; a++) {
        var tt = slots[a].t;
        st.slots.push({ slot: a, x: slots[a].x, y: slots[a].y, turret: tt ? { type: tt.type, tier: tt.tier, spent: tt.spent } : null });
      }
      for (var b = 0; b < enemies.length; b++) st.enemies.push(view(enemies[b]));
      var acts = strat.plan(st);
      if (acts && acts.length) {
        var na = Math.min(32, acts.length);
        for (var c = 0; c < na; c++) applyAction(acts[c]);
      }
      var wl = waves[wave];
      for (var q = 0; q < wl.length; q++) queue.push({ tick: tick + 4 * q, wave: wave, idx: q, type: wl[q] });
      queue.sort(function (u, v) { return u.tick - v.tick || u.wave - v.wave || u.idx - v.idx; });
      waves[wave - 1] = null;
      if (recorder && recorder.onWave) recorder.onWave(tick, wave, gold, waves[wave + 1].slice());
    }
    // 2. spawn
    while (queue.length && queue[0].tick === tick) {
      var qe = queue.shift();
      var e0 = makeEnemy(qe.type, qe.wave, Math.floor(ED[qe.type].hp * M[qe.wave] / 1000), 0);
      enemies.push(e0);
      if (recorder && recorder.onSpawn) recorder.onSpawn(tick, e0);
    }
    // 3. move
    var fell = false;
    for (var m = 0; m < enemies.length; m++) {
      var e = enemies[m];
      var sp = e.slow > 0 ? Math.floor(e.speed * 60 / 100) : e.speed;
      e.progress += sp;
      var rl = ROUTES[e.air].len;
      if (e.progress >= rl) {
        e.progress = rl; place(e);
        baseHp -= e.leak;
        log.push([tick, "L", e.id, baseHp]);
        if (recorder && recorder.onLeak) recorder.onLeak(tick, e, baseHp);
        enemies.splice(m, 1); m--;
        if (baseHp <= 0) {
          log.push([tick, "F", wave, 0]);
          fell = true; break;
        }
      } else place(e);
    }
    if (fell) { fallTick = tick; endTick = tick; if (recorder && recorder.onTick) recorder.onTick(tick, enemies, gold, baseHp, true); break; }
    // 4. age & heal
    for (var h = 0; h < enemies.length; h++) {
      var me = enemies[h];
      me.age++;
      if (me.type === "mender" && me.age % 20 === 0) {
        for (var h2 = 0; h2 < enemies.length; h2++) {
          var o = enemies[h2], hx = o.x - me.x, hy = o.y - me.y;
          if (hx * hx + hy * hy <= 22500) {
            o.hp += Math.floor(o.maxHp * 8 / 100);
            if (o.hp > o.maxHp) o.hp = o.maxHp;
          }
        }
        if (recorder && recorder.onHeal) recorder.onHeal(tick, me);
      }
    }
    // 5. turrets fire
    for (var s5 = 0; s5 < 16; s5++) {
      var T = slots[s5].t;
      if (!T) continue;
      if (T.cd > 0) { T.cd--; if (T.cd > 0) continue; }
      var D = TD[T.type], r2 = T.range * T.range, cands = [];
      for (var k = 0; k < enemies.length; k++) {
        var ce = enemies[k];
        if (ce.air ? !D.air : !D.ground) continue;
        var dx = ce.x - slots[s5].x, dy = ce.y - slots[s5].y;
        if (dx * dx + dy * dy <= r2) cands.push(ce);
      }
      if (!cands.length) continue;
      var tgt = null;
      if (typeof strat.target === "function") {
        var cv = [];
        for (var k2 = 0; k2 < cands.length; k2++) cv.push(view(cands[k2]));
        var rid = strat.target({ slot: s5, type: T.type, tier: T.tier, x: slots[s5].x, y: slots[s5].y, range: T.range }, cv);
        for (var k3 = 0; k3 < cands.length; k3++) if (cands[k3].id === rid) { tgt = cands[k3]; break; }
      }
      if (!tgt) {
        var best = Infinity;
        for (var k4 = 0; k4 < cands.length; k4++) {
          var rem = ROUTES[cands[k4].air].len - cands[k4].progress;
          if (rem < best) { best = rem; tgt = cands[k4]; }
        }
      }
      var hits;
      if (D.splash > 0) {
        hits = [];
        var sr2 = D.splash * D.splash;
        for (var k5 = 0; k5 < enemies.length; k5++) {
          var he = enemies[k5];
          if (he.air ? !D.air : !D.ground) continue;
          var ddx = he.x - tgt.x, ddy = he.y - tgt.y;
          if (ddx * ddx + ddy * ddy <= sr2) hits.push(he);
        }
      } else hits = [tgt];
      for (var k6 = 0; k6 < hits.length; k6++) {
        var hh = hits[k6];
        var dmg = D.pierce ? T.dmg : Math.max(1, T.dmg - hh.armor);
        hh.hp -= dmg;
        if (D.slow > 0) hh.slow = D.slow;
      }
      T.cd = D.period;
      if (recorder && recorder.onShot) recorder.onShot(tick, s5, T.type, T.tier, tgt, hits);
      var anyDead = false;
      for (var k7 = 0; k7 < enemies.length; k7++) if (enemies[k7].hp <= 0) { anyDead = true; break; }
      if (anyDead) {
        var alive = [], spawned = [];
        for (var k8 = 0; k8 < enemies.length; k8++) {
          var de = enemies[k8];
          if (de.hp > 0) { alive.push(de); continue; }
          gold += de.bounty;
          log.push([tick, "K", de.id, s5]);
          if (recorder && recorder.onKill) recorder.onKill(tick, de, s5);
          if (de.type === "splitter") {
            var shp = Math.max(1, Math.floor(de.maxHp / 4));
            for (var sp3 = 0; sp3 < 3; sp3++) {
              var sl3 = makeEnemy("splitling", de.wave, shp, de.progress);
              spawned.push(sl3);
              if (recorder && recorder.onSpawn) recorder.onSpawn(tick, sl3, de);
            }
          }
        }
        enemies = alive.concat(spawned);
      }
    }
    // 6. slow timers
    for (var s6 = 0; s6 < enemies.length; s6++) if (enemies[s6].slow > 0) enemies[s6].slow--;
    if (recorder && recorder.onTick) recorder.onTick(tick, enemies, gold, baseHp, false);
  }
  var js = JSON.stringify(log), hsh = 0x811c9dc5;
  for (var z = 0; z < js.length; z++) { hsh ^= js.charCodeAt(z); hsh = Math.imul(hsh, 0x01000193); }
  var hex = (hsh >>> 0).toString(16);
  while (hex.length < 8) hex = "0" + hex;
  return { score: Math.round((endTick - 20) * 2.5) / 100, fallTick: fallTick, log: log, hash: hex };
}

