// Parameterized strategy for tuning. GENOME = { types:[16], script:[slot,...], alpha, ... }
var GENOME = null;
function createStrategy() {
  var G = GENOME;
  var TD = {
    bolt: [50, 26, 0], cannon: [90, 60, 90], frost: [70, 10, 0], lance: [120, 180, 0], flak: [80, 40, 70]
  };
  var GR = [[50, 250], [650, 250], [650, 1050], [1250, 1050], [1250, 350], [1850, 350], [1850, 1150], [2350, 1150]];
  var AR = [[50, 650], [2150, 650], [2150, 1150], [2350, 1150]];
  function routeLen(r) { var l = 0; for (var i = 0; i + 1 < r.length; i++) l += Math.abs(r[i + 1][0] - r[i][0]) + Math.abs(r[i + 1][1] - r[i][1]); return l; }
  var GL = routeLen(GR), AL = routeLen(AR);
  function posOf(e) {
    var r = e.air ? AR : GR, p = (e.air ? AL : GL) - e.remaining;
    for (var i = 0; i + 1 < r.length; i++) {
      var l = Math.abs(r[i + 1][0] - r[i][0]) + Math.abs(r[i + 1][1] - r[i][1]);
      if (p <= l || i + 2 === r.length) {
        if (p > l) p = l;
        return [r[i][0] + Math.sign(r[i + 1][0] - r[i][0]) * p, r[i][1] + Math.sign(r[i + 1][1] - r[i][1]) * p];
      }
      p -= l;
    }
    return [0, 0];
  }
  function dmgOf(type, tier) { var d = TD[type][1]; for (var i = 1; i < tier; i++) d = Math.floor(d * 16 / 10); return d; }
  var ptr = 0;
  var script = G.script, types = G.types;
  return {
    plan: function (s) {
      var acts = [], gold = s.gold;
      var tiers = [], kinds = [];
      for (var i = 0; i < 16; i++) { var t = s.slots[i].turret; tiers.push(t ? t.tier : 0); kinds.push(t ? t.type : null); }
      while (ptr < script.length && acts.length < 32) {
        var sl = script[ptr], ty = types[sl];
        if (!ty) { ptr++; continue; }
        if (tiers[sl] === 0) {
          var c = TD[ty][0];
          if (gold < c) break;
          acts.push({ op: "build", slot: sl, type: ty }); gold -= c; tiers[sl] = 1; kinds[sl] = ty; ptr++;
        } else if (tiers[sl] < 3) {
          var uc = TD[kinds[sl]][0] * (tiers[sl] === 1 ? 1 : 2);
          if (gold < uc) break;
          acts.push({ op: "upgrade", slot: sl }); gold -= uc; tiers[sl]++; ptr++;
        } else ptr++;
      }
      return acts;
    },
    target: function (t, c) {
      var n = c.length;
      if (n === 1) return c[0].id;
      var ty = t.type, d = dmgOf(ty, t.tier), best = -1, bv = -Infinity, i, j, e;
      var alpha = G.alpha[ty];
      if (ty === "cannon" || ty === "flak") {
        var R = TD[ty][2], R2 = R * R, P = [];
        for (i = 0; i < n; i++) P.push(posOf(c[i]));
        for (i = 0; i < n; i++) {
          var v = 0;
          for (j = 0; j < n; j++) {
            var dx = P[j][0] - P[i][0], dy = P[j][1] - P[i][1];
            if (dx * dx + dy * dy <= R2) { e = c[j]; v += Math.min(e.hp, Math.max(1, d - e.armor)); }
          }
          v = v * (1 + alpha * (1 - c[i].remaining / (c[i].air ? AL : GL)));
          if (v > bv) { bv = v; best = c[i].id; }
        }
        return best;
      }
      for (i = 0; i < n; i++) {
        e = c[i];
        var eff = ty === "lance" ? d : Math.max(1, d - e.armor);
        var v2 = Math.min(e.hp, eff);
        if (ty === "frost") v2 = (e.slowed > 1 ? 0.2 : 1) * e.hp;
        v2 = v2 * (1 + alpha * (1 - e.remaining / (e.air ? AL : GL)));
        if (v2 > bv) { bv = v2; best = e.id; }
      }
      return best;
    }
  };
}

