load("sim.js"); load("strat.js");
GENOME = JSON.parse(readFile(arguments[0]));
var seeds = +(arguments[1] || 5);
for (var s = 1; s <= seeds; s++) {
  var leaks = {}, lastGold = 0, waveGold = [], kills = {}, shots = {}, dmgBy = {}, lastPlan = null;
  var rec = {
    onLeak: function (t, e, hp) { var k = e.type + "@w" + e.wave; leaks[k] = (leaks[k] || 0) + 1; },
    onWave: function (t, w, g) { waveGold.push(w + ":" + g); },
    onShot: function (t, s, ty, tier, tgt, hits) { shots[ty] = (shots[ty] || 0) + hits.length; }
  };
  var inner = createStrategy;
  var r = rampartSimulate(function () { var st = inner(); var p = st.plan; st.plan = function (x) { lastPlan = x; return p(x); }; return st; }, s, 12020, rec);
  print("seed", s, "score", r.score, "leaks", JSON.stringify(leaks));
  print("  gold by wave", waveGold.filter(function (_, i) { return i % 4 === 0; }).join(" "));
  print("  board", lastPlan.slots.map(function (x) { return x.turret ? x.turret.type[0] + x.turret.tier : "--"; }).join(" "), "hitsPerType", JSON.stringify(shots));
}

