load("sim.js"); load("strat.js");
var args = arguments;
var initFile = args[0], outFile = args[1], iters = +args[2], rs = +args[3], nTrain = +(args[4] || 30), seedBase = +(args[5] || 1);
var TYPES = [null, "bolt", "cannon", "frost", "lance", "flak"];
function norm(g) {
  var cnt = {}, sc = [];
  for (var i = 0; i < g.script.length; i++) { var s = g.script[i]; cnt[s] = (cnt[s] || 0) + 1; if (cnt[s] <= 3) sc.push(s); }
  for (var s2 = 0; s2 < 16; s2++) while ((cnt[s2] = (cnt[s2] || 0)) < 3) { sc.push(s2); cnt[s2]++; }
  g.script = sc; return g;
}
function fit(g) {
  GENOME = g; var t = 0;
  for (var s = seedBase; s < seedBase + nTrain; s++) t += rampartSimulate(createStrategy, s, 12020).score;
  return t / nTrain;
}
function clone(g) { return JSON.parse(JSON.stringify(g)); }
function ri(n) { return Math.floor(Math.random() * n); }
function mutate(g) {
  var n = 1 + ri(3);
  for (var k = 0; k < n; k++) {
    var r = Math.random(), L = g.script.length;
    if (r < 0.35) { var i = ri(L), j = ri(L), t = g.script[i]; g.script[i] = g.script[j]; g.script[j] = t; }
    else if (r < 0.7) { var a = ri(L), tok = g.script.splice(a, 1)[0]; var off = Math.random() < 0.5 ? (ri(7) - 3) : ri(L) - a; var b = Math.max(0, Math.min(L - 1, a + off)); g.script.splice(b, 0, tok); }
    else if (r < 0.9) { g.types[ri(16)] = TYPES[ri(6)]; }
    else { var keys = Object.keys(g.alpha), kk = keys[ri(keys.length)]; g.alpha[kk] = Math.max(0, g.alpha[kk] + (Math.random() - 0.5) * 1.0); }
  }
  return g;
}
var cur = norm(JSON.parse(readFile(initFile)));
var cf = fit(cur), best = clone(cur), bf = cf;
for (var it = 0; it < iters; it++) {
  var c = mutate(clone(cur)), f = fit(c);
  if (f >= cf) { cur = c; cf = f; if (f > bf) { bf = f; best = clone(c); writeFile(outFile, JSON.stringify(best)); } }
  if (it % 200 === 0) print(rs, it, cf.toFixed(3), bf.toFixed(3));
}
writeFile(outFile, JSON.stringify(best));
print("done", rs, bf.toFixed(3));

