(function () {
  "use strict";
  var DURATION = 100;
  var TPS = 20, MAX_TICKS = 2020;
  var TURRET_TYPES = ["bolt", "cannon", "frost", "lance", "flak"];
  var ENEMY_TYPES = ["grunt", "runner", "wisp", "brute", "splitter", "mender", "splitling"];
  var EIDX = {}; ENEMY_TYPES.forEach(function (t, i) { EIDX[t] = i; });
  var TIDX = {}; TURRET_TYPES.forEach(function (t, i) { TIDX[t] = i; });
  var SLOT_TILES = [[3, 3], [5, 5], [7, 4], [7, 8], [9, 9], [10, 5], [11, 8], [13, 8], [14, 5], [15, 2], [16, 7], [17, 4], [19, 8], [20, 10], [22, 9], [3, 7]];
  var GROUND_PTS = [[0, 2], [6, 2], [6, 10], [12, 10], [12, 3], [18, 3], [18, 11], [23, 11]];
  var AIR_PTS = [[0, 6], [21, 6], [21, 11], [23, 11]];
  var KEEP = { x: 23.5, z: 11.5 };
  var AIR_H = 0.8;

  // ------------------------------------------------------------------ seeded visual RNG
  function mulberryF(a) {
    return function () {
      a = (a + 0x6D2B79F5) | 0; var t = Math.imul(a ^ (a >>> 15), 1 | a);
      t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    };
  }
  var vrand = mulberryF(42);
  function vr(a, b) { return a + (b - a) * vrand(); }
  function clamp01(x) { return x < 0 ? 0 : x > 1 ? 1 : x; }
  function smooth(e0, e1, x) { var t = clamp01((x - e0) / (e1 - e0)); return t * t * (3 - 2 * t); }

  // ------------------------------------------------------------------ route geometry (visual only)
  function makeRoute(pts) {
    var p = pts.map(function (q) { return [q[0] + 0.5, q[1] + 0.5]; }), segs = [], len = 0;
    for (var i = 0; i + 1 < p.length; i++) {
      var l = Math.abs(p[i + 1][0] - p[i][0]) + Math.abs(p[i + 1][1] - p[i][1]);
      segs.push({ x: p[i][0], z: p[i][1], dx: Math.sign(p[i + 1][0] - p[i][0]), dz: Math.sign(p[i + 1][1] - p[i][1]), s: len, l: l });
      len += l;
    }
    return { pts: p, segs: segs, len: len };
  }
  var ROUTES = [makeRoute(GROUND_PTS), makeRoute(AIR_PTS)];
  function routePos(r, d, out) {
    var s = r.segs, i = 0;
    if (d < 0) d = 0; if (d > r.len) d = r.len;
    while (i < s.length - 1 && d > s[i].s + s[i].l) i++;
    var u = d - s[i].s;
    out.x = s[i].x + s[i].dx * u; out.z = s[i].z + s[i].dz * u;
    return out;
  }
  var _ra = { x: 0, z: 0 }, _rb = { x: 0, z: 0 };
  function routeHeading(r, d) {
    routePos(r, d - 0.18, _ra); routePos(r, d + 0.18, _rb);
    return Math.atan2(_rb.x - _ra.x, _rb.z - _ra.z);
  }

  // ------------------------------------------------------------------ replay precompute
  var REPLAY = (function () {
    var tickStart = new Int32Array(MAX_TICKS + 2);
    var cap = 1 << 16, n = 0;
    var eId = new Int32Array(cap), eProg = new Float32Array(cap), eHp = new Float32Array(cap), eFl = new Uint8Array(cap);
    function grow() {
      cap *= 2;
      var a = new Int32Array(cap); a.set(eId); eId = a;
      var b = new Float32Array(cap); b.set(eProg); eProg = b;
      var c = new Float32Array(cap); c.set(eHp); eHp = c;
      var d = new Uint8Array(cap); d.set(eFl); eFl = d;
    }
    var goldT = new Int32Array(MAX_TICKS), hpT = new Int8Array(MAX_TICKS);
    var shots = [], kills = [], heals = [], leaks = [], acts = [], waves = [], splits = [];
    var lastTick = 0, maxOnScreen = 0;
    var rec = {
      onWave: function (t, w, g, next) { waves.push({ t: t, w: w, next: next }); },
      onAction: function (t, op, slot, type, tier) { acts.push({ t: t, op: op, slot: slot, type: type, tier: tier }); },
      onLeak: function (t, e, hp) { leaks.push({ t: t, id: e.id, type: e.type, hp: hp }); },
      onHeal: function (t, e) { heals.push({ t: t, x: e.x / 100, z: e.y / 100 }); },
      onShot: function (t, s, type, tier, tgt, hits) { shots.push({ t: t, s: s, ty: TIDX[type], tier: tier, x: tgt.x / 100, z: tgt.y / 100, air: tgt.air, n: hits.length }); },
      onKill: function (t, e, s) { kills.push({ t: t, id: e.id, type: EIDX[e.type], x: e.x / 100, z: e.y / 100, air: e.air, s: s }); },
      onSpawn: function (t, e, parent) { if (parent && e.id % 3 === 0) splits.push({ t: t, x: e.x / 100, z: e.y / 100 }); },
      onTick: function (t, enemies, gold, hp) {
        tickStart[t] = n;
        for (var i = 0; i < enemies.length; i++) {
          if (n >= cap) grow();
          var e = enemies[i];
          eId[n] = e.id; eProg[n] = e.progress / 100; eHp[n] = Math.max(0, e.hp) / e.maxHp;
          eFl[n] = EIDX[e.type] | (e.air ? 8 : 0) | (e.slow > 0 ? 16 : 0);
          n++;
        }
        tickStart[t + 1] = n;
        goldT[t] = gold; hpT[t] = hp; lastTick = t;
        if (enemies.length > maxOnScreen) maxOnScreen = enemies.length;
      }
    };
    var res = rampartSimulate(createStrategy, 42, MAX_TICKS, rec);
    // board snapshots
    var boards = [], cur = [];
    for (var i = 0; i < 16; i++) cur.push(null);
    boards.push({ t: -1, b: cur.slice() });
    for (var a = 0; a < acts.length; a++) {
      var ac = acts[a];
      if (ac.op === "S") cur[ac.slot] = null; else cur[ac.slot] = { type: ac.type, tier: ac.tier };
      if (a + 1 === acts.length || acts[a + 1].t !== ac.t) boards.push({ t: ac.t, b: cur.slice() });
    }
    // aim angles per slot per tick
    var aim = new Float32Array(MAX_TICKS * 16);
    var lastShot = new Int32Array(MAX_TICKS * 16).fill(-1);
    var ang = [], ls = [];
    for (var s0 = 0; s0 < 16; s0++) { ang.push(Math.PI); ls.push(-1); }
    var si = 0;
    for (var t = 0; t < MAX_TICKS; t++) {
      while (si < shots.length && shots[si].t === t) {
        var sh = shots[si];
        var sx = SLOT_TILES[sh.s][0] + 0.5, sz = SLOT_TILES[sh.s][1] + 0.5;
        ang[sh.s] = Math.atan2(sh.x - sx, sh.z - sz); ls[sh.s] = si; si++;
      }
      for (var s1 = 0; s1 < 16; s1++) { aim[t * 16 + s1] = ang[s1]; lastShot[t * 16 + s1] = ls[s1]; }
    }
