old_end=s.index('  };\n}', old_start)
new='''    target: function (t, c) {
      var n = c.length;
      if (n === 1) return c[0].id;
      var ty = t.type, d = dmgOf(ty, t.tier), best = -1, bv = -Infinity, i, j, e;
      var alpha = G.alpha[ty], W = G.W ? G.W[ty] : null, K = G.K ? G.K[ty] : 0;
      var V = [];
      for (i = 0; i < n; i++) {
        e = c[i];
        var eff = ty === \"lance\" ? d : Math.max(1, d - e.armor);
        var w = W ? (W[e.type] === undefined ? 1 : W[e.type]) : 1;
        var u = 1 + alpha * (1 - e.remaining / (e.air ? AL : GL));
        var v;
        if (ty === \"frost\") v = w * e.hp * (e.slowed > 1 ? G.fs : 1) * u;
        else v = (Math.min(e.hp, eff) + (eff >= e.hp ? K * d : 0)) * w * u;
        V.push(v);
      }
      if (ty === \"cannon\" || ty === \"flak\") {
        var R = TD[ty][2], R2 = R * R, P = [];
        for (i = 0; i < n; i++) P.push(posOf(c[i]));
        for (i = 0; i < n; i++) {
          var s2 = 0;
          for (j = 0; j < n; j++) {
            var dx = P[j][0] - P[i][0], dy = P[j][1] - P[i][1];
            if (dx * dx + dy * dy <= R2) s2 += V[j];
          }
          if (s2 > bv) { bv = s2; best = c[i].id; }
        }
        return best;
      }
      for (i = 0; i < n; i++) if (V[i] > bv) { bv = V[i]; best = c[i].id; }
      return best;
    }
