(function () {
  var out = [], fails = 0, ts = 0;
  function pump(ms) { ts += ms; var q = window.__rafQ; window.__rafQ = []; q.forEach(function (cb) { cb(ts); }); }
  function run(sec, step) { step = step || 16.7; var n = Math.round(sec * 1000 / step); for (var i = 0; i < n; i++) pump(step); }
  var cd = document.getElementById('countdown'), sc = document.getElementById('scrubber'), tg = document.getElementById('btn-toggle'), rf = document.getElementById('btn-refire');
  var ip = document.getElementById('icon-pause'), ipl = document.getElementById('icon-play');
  var pills = document.querySelectorAll('.speed-pill');
  function st() { return window.__rampart.getState(); }
  function check(name, cond, info) { if (!cond) fails++; out.push((cond ? 'ok   ' : 'FAIL ') + name + (info ? ' [' + info + ']' : '')); }
  var vis = function (el) { return el.style.display !== 'none'; };
  check('initial countdown 3', cd.textContent === '3' && vis(cd) && sc.value === '0');
  pump(0);
  check('first rAF -> COUNTDOWN "3"', st().state === 'COUNTDOWN' && cd.textContent === '3' && cd.style.display === 'block');
  run(0.98);
  check('0.98s still "3", simTime 0', cd.textContent === '3' && st().simTime === 0 && sc.value === '0', cd.textContent);
  run(0.05);
  check('~1.03s "2"', cd.textContent === '2', cd.textContent);
  run(1.0);
  check('~2.03s "1"', cd.textContent === '1', cd.textContent);
  run(0.95);
  check('~2.98s "1" still COUNTDOWN', cd.textContent === '1' && st().state === 'COUNTDOWN', st().state);
  run(0.1);
  check('>=3s hidden, PLAYING', cd.style.display === 'none' && cd.textContent === '' && st().state === 'PLAYING', st().state + ' ' + st().simTime.toFixed(3));
  run(1.0);
  check('playing 1s at 1x', Math.abs(st().simTime - 1.0) < 0.06 && sc.value === st().simTime.toFixed(3), st().simTime.toFixed(3) + ' sv=' + sc.value);
  // big frame gap clamp
  var before = st().simTime; pump(5000);
  check('dt clamp 0.1', Math.abs(st().simTime - before - 0.1) < 1e-9, (st().simTime - before).toFixed(4));
  tg.click();
  check('toggle -> PAUSED', st().state === 'PAUSED' && tg.getAttribute('aria-label') === 'Play' && !vis(ip) && vis(ipl));
  var ps = st().simTime; run(0.5);
  check('paused freezes', st().simTime === ps);
  tg.click();
  check('toggle -> PLAYING', st().state === 'PLAYING' && tg.getAttribute('aria-label') === 'Pause' && vis(ip) && !vis(ipl));
  pills[3].click();
  var act = Array.prototype.map.call(pills, function (p) { return p.classList.contains('is-active') + '/' + p.getAttribute('aria-checked'); }).join(',');
  check('speed 2x pill', st().speed === 2 && act === 'false/false,false/false,false/false,true/true', act);
  before = st().simTime; run(1.0);
  check('2x advances ~2s', Math.abs(st().simTime - before - 2) < 0.08, (st().simTime - before).toFixed(3));
  rf.click();
  check('refire -> REFIRE_HOLD', st().state === 'REFIRE_HOLD' && st().simTime === 0 && sc.value === '0' && cd.style.display === 'none' && tg.getAttribute('aria-label') === 'Pause' && vis(ip));
  run(0.95);
  check('hold 0.95s still holding, countdown hidden', st().state === 'REFIRE_HOLD' && cd.style.display === 'none' && st().simTime === 0);
  run(0.1);
  check('hold done -> PLAYING, speed kept', st().state === 'PLAYING' && st().speed === 2, st().state);
  sc.value = '42.5'; sc.dispatchEvent(new Event('input'));
  check('scrub -> PAUSED at 42.5', st().state === 'PAUSED' && st().simTime === 42.5 && tg.getAttribute('aria-label') === 'Play');
  tg.click(); run(30, 50);
  check('plays to end -> ENDED', st().state === 'ENDED' && st().simTime === 100 && sc.value === '100.000' && tg.getAttribute('aria-label') === 'Play' && vis(ipl) && !vis(ip), st().state + ' ' + st().simTime + ' ' + sc.value);
  tg.click();
  check('ENDED toggle -> PLAYING from 0', st().state === 'PLAYING' && st().simTime === 0 && cd.style.display === 'none');
  rf.click(); tg.click();
  check('toggle during REFIRE_HOLD -> PAUSED at 0', st().state === 'PAUSED' && st().simTime === 0 && cd.style.display === 'none');
  // determinism: render same simTime after different histories -> same pixels
  var cv = document.getElementById('stage'), gl = cv.getContext('webgl2') || cv.getContext('webgl');
  function snap(t) { window.__rampart.renderAt(t); var w = 64, h = 64, px = new Uint8Array(w * h * 4); gl.readPixels((cv.width >> 1) - 32, (cv.height >> 1) - 32, w, h, gl.RGBA, gl.UNSIGNED_BYTE, px); var hsh = 0; for (var i = 0; i < px.length; i++) hsh = (hsh * 31 + px[i]) | 0; return hsh; }
  var a1 = snap(63.437); snap(90); snap(12.1); var a2 = snap(63.437); snap(5); var a3 = snap(63.437);
  check('scrub determinism (same simTime -> same pixels)', a1 === a2 && a2 === a3, a1 + ' ' + a2 + ' ' + a3);
  var d = document.createElement('div');
  d.style.cssText = 'position:fixed;top:10px;left:10px;color:#fff;font:15px monospace;z-index:999;background:#000d;white-space:pre;padding:8px';
  d.textContent = 'STATE MACHINE TEST: ' + (fails ? fails + ' FAILURES' : 'ALL PASS') + '\n' + out.join('\n') + '\nerrors: ' + JSON.stringify(window.__errs);
  document.body.appendChild(d);
})();

